pub struct Inflector;

impl Inflector {
    pub fn initialize() {}

    pub fn pluralize(word: &str) -> Vec<u8> {
        let mut output = word.as_bytes().to_vec();
        output.push(b's');
        output
    }

    pub fn ordinalize(number: i32) -> Vec<u8> {
        let suffix = if (number % 100) / 10 == 1 {
            "th"
        } else {
            match number % 10 {
                1 => "st",
                2 => "nd",
                3 => "rd",
                _ => "th",
            }
        };

        format!("{number}{suffix}").into_bytes()
    }

    pub fn camelize(word: &str, lowercase_first_letter: bool) -> Vec<u8> {
        let mut output = Vec::with_capacity(word.len());

        for (index, segment) in word.as_bytes().split(|byte| *byte == b'_').enumerate() {
            if segment.is_empty() {
                continue;
            }

            if lowercase_first_letter && output.is_empty() && index == 0 {
                output.extend_from_slice(segment);
            } else {
                output.extend_from_slice(&camel_segment(segment));
            }
        }

        output
    }

    pub fn titleize(word: &str) -> Vec<u8> {
        titleize_bytes(word.as_bytes())
    }

    pub fn capitalize(word: &str) -> Vec<u8> {
        capitalize_bytes(word.as_bytes())
    }

    pub fn truncate(word: &str, length: usize) -> Vec<u8> {
        Self::truncate_with_omission(word, length, "...")
    }

    pub fn truncate_with_omission(word: &str, length: usize, omission: &str) -> Vec<u8> {
        let bytes = word.as_bytes();
        let omission_bytes = omission.as_bytes();

        if bytes.len() <= length {
            return bytes.to_vec();
        }

        if length <= omission_bytes.len() {
            return omission_bytes[..length].to_vec();
        }

        let keep = length - omission_bytes.len();
        let mut output = bytes[..keep].to_vec();
        output.extend_from_slice(omission_bytes);
        output
    }

    pub fn parameterize(word: &str) -> Vec<u8> {
        Self::parameterize_with_separator(word, "-")
    }

    pub fn parameterize_with_separator(word: &str, separator: &str) -> Vec<u8> {
        let separator_bytes = separator.as_bytes();
        let mut output = Vec::with_capacity(word.len());

        for &byte in word.as_bytes() {
            match byte {
                b'a'..=b'z' | b'0'..=b'9' => output.push(byte),
                b'A'..=b'Z' => output.push(ascii_lower(byte)),
                b' ' => output.extend_from_slice(separator_bytes),
                _ => {}
            }
        }

        trim_sequence(output, separator_bytes)
    }

    pub fn is_plural(word: &str) -> bool {
        word.as_bytes().last() == Some(&b's')
    }
}

fn ascii_upper(byte: u8) -> u8 {
    if byte.is_ascii_lowercase() {
        byte - (b'a' - b'A')
    } else {
        byte
    }
}

fn ascii_lower(byte: u8) -> u8 {
    if byte.is_ascii_uppercase() {
        byte + (b'a' - b'A')
    } else {
        byte
    }
}

fn camel_segment(segment: &[u8]) -> Vec<u8> {
    if segment.is_empty() {
        return Vec::new();
    }

    let mut output = Vec::with_capacity(segment.len());
    output.push(ascii_upper(segment[0]));
    output.extend_from_slice(&segment[1..]);
    output
}

fn capitalize_bytes(bytes: &[u8]) -> Vec<u8> {
    if bytes.is_empty() {
        return Vec::new();
    }

    let mut output = Vec::with_capacity(bytes.len());
    output.push(ascii_upper(bytes[0]));
    for &byte in &bytes[1..] {
        output.push(ascii_lower(byte));
    }
    output
}

fn titleize_bytes(bytes: &[u8]) -> Vec<u8> {
    let mut output = Vec::with_capacity(bytes.len());
    let mut start = 0;

    for index in 0..=bytes.len() {
        if index == bytes.len() || bytes[index] == b' ' {
            output.extend_from_slice(&capitalize_bytes(&bytes[start..index]));
            if index < bytes.len() {
                output.push(b' ');
            }
            start = index + 1;
        }
    }

    output
}

fn trim_sequence(bytes: Vec<u8>, pattern: &[u8]) -> Vec<u8> {
    if pattern.is_empty() {
        return bytes;
    }

    let mut start = 0;
    while start + pattern.len() <= bytes.len()
        && &bytes[start..start + pattern.len()] == pattern
    {
        start += pattern.len();
    }

    let mut end = bytes.len();
    while start + pattern.len() <= end && &bytes[end - pattern.len()..end] == pattern {
        end -= pattern.len();
    }

    bytes[start..end].to_vec()
}

